package com.example.TuVanSinhVien.controller;

import com.example.TuVanSinhVien.entity.BaiVietHuongDan;
import com.example.TuVanSinhVien.entity.CauHoiFAQ;
import com.example.TuVanSinhVien.service.CatalogService;
import com.example.TuVanSinhVien.service.ContentService;
import com.example.TuVanSinhVien.service.ReportService;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

@Controller
public class HomeController {
    private final ContentService contentService;
    private final CatalogService catalogService;
    private final ReportService reportService;

    @GetMapping("/")
    public String index(@RequestParam(required = false) String logout, Model model) {
        if (logout != null) {
            model.addAttribute("logoutMessage", "Bạn đã đăng xuất khỏi hệ thống thành công.");
        }
        model.addAttribute("faqs", contentService.getPublicFaqs(null, null));
        model.addAttribute("articles", contentService.getPublicArticles(null, null));
        model.addAttribute("advisors", catalogService.getAllActiveAdvisors());
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        model.addAttribute("stats", reportService.getDashboardSummary());
        return "public/index";
    }

    @GetMapping("/faq")
    public String faq(@RequestParam(required = false) Integer linhVuc, @RequestParam(required = false) String kw, Model model) {
        model.addAttribute("faqs", contentService.getPublicFaqs(linhVuc, kw));
        model.addAttribute("linhVucList", catalogService.getAllActiveLinhVuc());
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        model.addAttribute("selectedLinhVuc", linhVuc);
        model.addAttribute("kw", kw);
        return "public/faq";
    }

    @GetMapping("/articles")
    public String articles(@RequestParam(required = false) Integer linhVuc, @RequestParam(required = false) String kw, Model model) {
        model.addAttribute("articles", contentService.getPublicArticles(linhVuc, kw));
        model.addAttribute("linhVucList", catalogService.getAllActiveLinhVuc());
        model.addAttribute("selectedLinhVuc", linhVuc);
        model.addAttribute("kw", kw);
        return "public/articles";
    }

    @GetMapping("/articles/{id}")
    public String articleDetail(@PathVariable Integer id, Model model) {
        BaiVietHuongDan article = contentService.getArticleAndIncrementView(id);
        if (article == null) {
            return "redirect:/articles";
        }
        model.addAttribute("article", article);
        model.addAttribute("recentArticles", contentService.getPublicArticles(null, null));
        return "public/article-detail";
    }

    @GetMapping("/advisors")
    public String advisors(Model model) {
        model.addAttribute("advisors", catalogService.getAllActiveAdvisors());
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        return "public/advisors";
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public HomeController(final ContentService contentService, final CatalogService catalogService, final ReportService reportService) {
        this.contentService = contentService;
        this.catalogService = catalogService;
        this.reportService = reportService;
    }
}
